* { box-sizing: border-box; }
:root {
  --ink: #17201e;
  --muted: #66716e;
  --line: #dce2df;
  --canvas: #f3f5f2;
  --panel: #ffffff;
  --forest: #173f38;
  --forest-soft: #e8f0ed;
  --amber: #9a5b12;
  --amber-soft: #fff3dc;
  --red: #a43c35;
  --red-soft: #fcecea;
  --shadow: 0 1px 2px rgba(21, 40, 35, 0.05), 0 10px 30px rgba(21, 40, 35, 0.04);
}
body {
  margin: 0;
  background: var(--canvas);
  color: var(--ink);
  font-family: Inter, ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}
button, select, textarea, input { font: inherit; }
button, select { cursor: pointer; }
.renewal-shell { min-height: 100vh; background: var(--canvas); }
.topbar {
  min-height: 76px;
  display: grid;
  grid-template-columns: 250px 1fr auto;
  align-items: center;
  gap: 24px;
  padding: 14px 22px;
  background: var(--forest);
  color: #fff;
}
.brand { display: flex; align-items: center; gap: 11px; font-size: 15px; font-weight: 760; letter-spacing: -0.01em; }
.brand-mark {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(255,255,255,0.3);
  border-radius: 10px;
  background: rgba(255,255,255,0.1);
  font-family: Georgia, serif;
  font-size: 20px;
}
.meeting-context { display: flex; flex-direction: column; gap: 3px; }
.meeting-context strong { font-size: 15px; font-weight: 650; }
.eyebrow { color: #6b7773; font-size: 11px; font-weight: 760; letter-spacing: 0.09em; text-transform: uppercase; }
.topbar .eyebrow { color: rgba(255,255,255,0.62); }
.top-actions { display: flex; align-items: center; gap: 12px; }
.count { color: rgba(255,255,255,0.72); font-size: 13px; }
.button {
  min-height: 38px;
  border: 1px solid transparent;
  border-radius: 9px;
  padding: 0 14px;
  font-weight: 700;
  font-size: 13px;
}
.button.secondary { border-color: rgba(255,255,255,0.25); background: rgba(255,255,255,0.08); color: #fff; }
.button.primary { width: 100%; background: var(--forest); color: #fff; }
.button.ghost { width: 100%; border-color: var(--line); background: #fff; color: #45504d; }
.button:disabled { cursor: not-allowed; opacity: 0.5; }
.workspace {
  display: grid;
  grid-template-columns: 250px minmax(0, 1fr) 320px;
  gap: 16px;
  max-width: 1365px;
  margin: 0 auto;
  padding: 18px;
  align-items: start;
}
.queue, .handoff, .case-card, .decision-card, .review-header, .diagnostics {
  border: 1px solid var(--line);
  background: var(--panel);
  box-shadow: var(--shadow);
}
.queue, .handoff { border-radius: 14px; overflow: hidden; }
.panel-heading { padding: 18px 18px 14px; border-bottom: 1px solid var(--line); }
.panel-heading h2 { margin: 4px 0 0; font-size: 16px; letter-spacing: -0.02em; }
.queue nav { display: flex; flex-direction: column; padding: 8px; gap: 5px; }
.account-row {
  width: 100%;
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 5px 10px;
  padding: 12px;
  border: 1px solid transparent;
  border-radius: 10px;
  background: transparent;
  color: var(--ink);
  text-align: left;
}
.account-row:hover { background: #f5f7f5; }
.account-row.selected { border-color: #b9cec7; background: var(--forest-soft); }
.account-row strong { font-size: 13px; }
.account-row .amount { color: #35413e; font-size: 12px; font-weight: 750; }
.account-row small { grid-column: 1 / -1; color: var(--muted); font-size: 12px; }
.account-row.selected small { color: #3d5b54; }
.queue-footer { margin: 8px 14px 14px; padding: 12px; border-radius: 10px; background: #f6f7f5; }
.queue-footer span { display: block; color: var(--muted); font-size: 11px; }
.queue-footer strong { display: block; margin-top: 4px; font-size: 12px; }
.review { min-width: 0; display: flex; flex-direction: column; gap: 13px; }
.review-header { display: flex; justify-content: space-between; gap: 20px; padding: 19px 20px; border-radius: 14px; }
.account-kicker { margin: 0 0 5px; color: var(--muted); font-size: 12px; font-weight: 680; }
.review-header h1 { margin: 0; font-size: 25px; line-height: 1.15; letter-spacing: -0.035em; }
.account-meta { display: flex; gap: 8px; align-items: center; margin: 9px 0 0; color: var(--muted); font-size: 13px; }
.meta-dot { color: #a1aaa7; }
.risk-badge { align-self: flex-start; border: 1px solid #f0c7c1; border-radius: 999px; padding: 7px 10px; background: var(--red-soft); color: var(--red); font-size: 12px; font-weight: 760; white-space: nowrap; }
.signal-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; }
.signal {
  min-height: 94px;
  padding: 14px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: #fff;
}
.signal span { display: block; color: var(--muted); font-size: 11px; font-weight: 680; }
.signal strong { display: block; margin-top: 8px; font-size: 18px; letter-spacing: -0.02em; }
.signal small { display: block; margin-top: 4px; color: var(--muted); font-size: 11px; }
.signal.danger strong { color: var(--red); }
.signal.warning strong { color: var(--amber); }
.card-heading { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; }
.card-heading h2 { margin: 0; font-size: 16px; letter-spacing: -0.02em; }
.card-heading p { margin: 4px 0 0; color: var(--muted); font-size: 12px; line-height: 1.45; }
.case-card, .decision-card { border-radius: 14px; padding: 17px 18px; }
.evidence-list { display: grid; gap: 8px; margin-top: 14px; }
.evidence-row { display: grid; grid-template-columns: 28px 1fr auto; gap: 10px; align-items: center; padding: 10px 11px; border: 1px solid #e7ebe8; border-radius: 10px; }
.evidence-icon { width: 26px; height: 26px; display: grid; place-items: center; border-radius: 8px; background: #f1f4f2; color: #50605c; font-size: 12px; font-weight: 800; }
.evidence-copy strong { display: block; font-size: 12px; }
.evidence-copy span { display: block; margin-top: 2px; color: var(--muted); font-size: 11px; }
.evidence-state { color: var(--red); font-size: 11px; font-weight: 760; }
.evidence-state.missing { color: var(--amber); }
.gap-badge { border-radius: 999px; padding: 6px 9px; background: var(--amber-soft); color: var(--amber); font-size: 11px; font-weight: 760; white-space: nowrap; }
.decision-options { display: grid; grid-template-columns: repeat(3, 1fr); gap: 9px; margin-top: 14px; }
.decision-option { position: relative; display: block; }
.decision-option input { position: absolute; opacity: 0; pointer-events: none; }
.option-body { min-height: 124px; display: flex; flex-direction: column; padding: 12px; border: 1px solid var(--line); border-radius: 11px; background: #fff; }
.option-top { display: flex; justify-content: space-between; gap: 8px; align-items: center; }
.option-title { font-size: 12px; font-weight: 780; }
.radio-mark { width: 16px; height: 16px; flex: 0 0 auto; border: 1.5px solid #a8b1ae; border-radius: 50%; box-shadow: inset 0 0 0 3px #fff; }
.option-body p { margin: 8px 0 0; color: var(--muted); font-size: 11px; line-height: 1.45; }
.option-note { margin-top: auto; padding-top: 9px; color: var(--amber); font-size: 10px; font-weight: 760; }
.decision-option input:checked + .option-body { border-color: var(--forest); background: var(--forest-soft); box-shadow: inset 0 0 0 1px var(--forest); }
.decision-option input:checked + .option-body .radio-mark { border-color: var(--forest); background: var(--forest); }
.decision-option input:focus-visible + .option-body { outline: 3px solid rgba(23,63,56,0.18); outline-offset: 2px; }
.diagnostics { border-radius: 11px; box-shadow: none; }
.diagnostics summary { padding: 12px 14px; color: #53605d; font-size: 12px; font-weight: 720; cursor: pointer; }
.diagnostic-content { padding: 0 14px 14px; color: var(--muted); font-size: 11px; line-height: 1.5; }
.diagnostic-content p { margin: 0; }
.handoff-body { display: flex; flex-direction: column; gap: 14px; padding: 16px; }
.readiness { padding: 12px; border: 1px solid #efd5a6; border-radius: 10px; background: var(--amber-soft); }
.readiness strong { display: block; color: #75430c; font-size: 12px; }
.readiness p { margin: 5px 0 0; color: #82551e; font-size: 11px; line-height: 1.45; }
.decision-summary { display: grid; grid-template-columns: 1fr auto; gap: 5px 10px; padding-bottom: 13px; border-bottom: 1px solid var(--line); }
.decision-summary span { color: var(--muted); font-size: 11px; }
.decision-summary strong { color: var(--forest); font-size: 12px; }
.field { display: flex; flex-direction: column; gap: 6px; color: #46514e; font-size: 11px; font-weight: 720; }
.field select, .field textarea { width: 100%; border: 1px solid #ccd5d1; border-radius: 9px; background: #fff; color: var(--ink); outline: none; }
.field select { height: 38px; padding: 0 10px; }
.field textarea { min-height: 74px; resize: none; padding: 10px; line-height: 1.4; }
.field select:focus, .field textarea:focus { border-color: var(--forest); box-shadow: 0 0 0 3px rgba(23,63,56,0.1); }
.handoff-facts { margin: 0; display: grid; gap: 10px; }
.handoff-facts div { padding: 10px; border-radius: 9px; background: #f6f7f5; }
.handoff-facts dt { color: var(--muted); font-size: 10px; font-weight: 740; text-transform: uppercase; letter-spacing: 0.06em; }
.handoff-facts dd { margin: 4px 0 0; font-size: 12px; line-height: 1.4; font-weight: 620; }
.action-stack { display: grid; gap: 8px; }
.lock-note { margin: 0; color: var(--muted); font-size: 10px; line-height: 1.4; text-align: center; }
@media (max-width: 1100px) {
  .workspace { grid-template-columns: 220px minmax(0, 1fr); }
  .handoff { grid-column: 2; }
  .topbar { grid-template-columns: 220px 1fr auto; }
}

